class Solution {
public:
    TreeNode* canMerge(vector<TreeNode*>& trees) {
        unordered_map<int, TreeNode*> m;
        unordered_set<int> leaves;
        for (auto t : trees) {
            m[t->val] = t;
            if (t->left) leaves.insert(t->left->val);
            if (t->right) leaves.insert(t->right->val);
        }
        TreeNode* root = nullptr;
        for (auto t : trees) {
            if (!leaves.count(t->val)) {
                root = t;
                break;
            }
        }
        if (!root) return nullptr;

        m.erase(root->val);
        function<bool(TreeNode*, int, int)> dfs = [&](TreeNode* node, int lo, int hi) {
            if (!node) return true;
            if (node->val <= lo || node->val >= hi) return false;
            if (!node->left && !node->right && m.count(node->val)) {
                TreeNode* t = m[node->val];
                node->left = t->left;
                node->right = t->right;
                m.erase(node->val);
            }
            return dfs(node->left, lo, node->val) && dfs(node->right, node->val, hi);
        };

        if (!dfs(root, INT_MIN, INT_MAX) || !m.empty()) return nullptr;
        return root;
    }
};
